/**
 * 侧边栏：只含产品大类（som / sbc / edge-computers / edge-ai / accessories）
 *
 * 目录树即分类树——每个文件夹的 _category_.json 决定名称、顺序、落地页。
 * 加一个产品分类 = 建文件夹 + 加 _category_.json，在下面补一行 autogenerated 即可。
 *
 * 工具类章节（getting-started / software / hardware / downloads / faq / community）
 * 不出现在侧边栏，通过顶部导航访问；这些页面用 displayed_sidebar: docsSidebar
 * 保持侧边栏显示一致。
 *
 * @type {import('@docusaurus/plugin-content-docs').SidebarsConfig}
 */
const sidebars = {
  docsSidebar: [
    { type: 'autogenerated', dirName: 'som' },
    { type: 'autogenerated', dirName: 'sbc' },
    { type: 'autogenerated', dirName: 'edge-computers' },
    { type: 'autogenerated', dirName: 'edge-ai' },
    { type: 'autogenerated', dirName: 'accessories' },
  ],
};

module.exports = sidebars;
